6	export interface PlatformConfig {
7	  max_resumes_per_job: number;
8	  max_file_size_mb: number;
9	  resume_retention_days: number;
10	  booking_embed_url: string | null;
11	  app_name: string;
12	  app_logo_url: string | null;
13	}
14	
15	const DEFAULTS: PlatformConfig = {
16	  max_resumes_per_job: 10,
17	  max_file_size_mb: 5,
18	  resume_retention_days: 30,
19	  booking_embed_url: null,
20	  app_name: "Rankora",
21	  app_logo_url: null,
22	};
23	
24	export const usePlatformConfig = () => {
25	  return useQuery({
26	    queryKey: ["platform_config"],
27	    queryFn: async (): Promise<PlatformConfig> => {
28	      const { data, error } = await supabase.rpc("get_public_platform_config");
29	      if (error || !data) return DEFAULTS;
30	      // RPC RETURNS TABLE gives an array; pick first row
31	      const row = Array.isArray(data) ? data[0] : data;
32	      if (!row) return DEFAULTS;
33	      return { ...DEFAULTS, ...row };
34	    },
35	    retry: false,
36	    placeholderData: DEFAULTS,
37	  });
38	};
