17	/**
18	 * Hook to read all feature flags with real-time updates.
19	 * Returns a map of flag key → { enabled, value_json }.
20	 */
21	export function useFeatureFlags() {
22	  const qc = useQueryClient();
23	
24	  const { data: flags, isLoading } = useQuery({
25	    queryKey: ["feature_flags"],
26	    queryFn: async () => {
27	      const { data, error } = await supabase
28	        .from("feature_flags")
29	        .select("*")
30	        .order("key");
31	      if (error) throw error;
32	      return data as FeatureFlag[];
33	    },
34	    staleTime: 60_000,
35	  });
36	
37	  useEffect(() => {
38	    const channel = supabase
39	      .channel("feature_flags_realtime")
40	      .on(
41	        "postgres_changes",
42	        { event: "*", schema: "public", table: "feature_flags" },
43	        () => {
44	          qc.invalidateQueries({ queryKey: ["feature_flags"] });
45	        }
46	      )
47	      .subscribe();
48	
49	    return () => {
50	      supabase.removeChannel(channel);
51	    };
52	  }, [qc]);
53	
54	  const flagMap = new Map<string, { enabled: boolean; value_json: Record<string, any> }>();
55	  flags?.forEach((f) => flagMap.set(f.key, { enabled: f.enabled, value_json: f.value_json }));
56	
57	  return { flags: flagMap, isLoading };
58	}
59	
60	/**
61	 * Hook to check a single feature flag by key.
62	 * Returns { enabled, value, isLoading }.
63	 */
64	export function useFeatureFlag(key: string) {
65	  const { flags, isLoading } = useFeatureFlags();
66	  const flag = flags.get(key);
67	  return {
68	    enabled: flag?.enabled ?? false,
69	    value: flag?.value_json ?? {},
70	    isLoading,
71	    ready: !isLoading,
72	  };
73	}
