3	import { useEffect, useCallback } from "react";
4	import { useRouter, useSearchParams } from "next/navigation";
5	import { useAuth } from "@/hooks/useAuth";
6	import { supabase } from "@/integrations/supabase/client";
7	import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
8	import { Zap } from "lucide-react";
9	import { toast } from "sonner";
10	import AuthForm from "@/components/AuthForm";
11	
12	const Auth = () => {
13	  const { user, loading } = useAuth();
14	  const router = useRouter();
15	  const searchParams = useSearchParams();
16	  const inviteToken = searchParams?.get("invite") ?? null;
17	  // Open-redirect protection: only allow same-origin paths starting with
18	  // a single "/" (not "//" or "/\" which can become protocol-relative).
19	  const rawNext = searchParams?.get("next") ?? "/";
20	  const nextPath = /^\/(?![/\\])/.test(rawNext) ? rawNext : "/";
21	
22	  const acceptInvite = useCallback(async (token: string) => {
23	    try {
24	      const { data: { session } } = await supabase.auth.getSession();
25	      if (!session?.access_token) return;
26	
27	      const res = await fetch(
28	        `${process.env.NEXT_PUBLIC_SUPABASE_URL}/functions/v1/accept-team-invite`,
29	        {
30	          method: "POST",
31	          headers: {
32	            "Content-Type": "application/json",
33	            "Authorization": `Bearer ${session.access_token}`,
34	            "apikey": process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY ?? "",
35	          },
36	          body: JSON.stringify({ token }),
37	        }
38	      );
39	
40	      const json = await res.json();
41	      if (res.ok && json.success) {
42	        toast.success(`Joined team: ${json.team_name ?? "Team"}`);
43	        router.replace("/team");
44	        return;
45	      }
46	    } catch {
47	      // Silently fail — user can accept invite manually later
48	    }
49	    router.replace(nextPath);
50	  }, [router, nextPath]);
51	
52	  useEffect(() => {
53	    if (!loading && user) {
54	      if (inviteToken) {
55	        acceptInvite(inviteToken);
56	      } else {
57	        router.replace(nextPath);
58	      }
59	    }
60	  }, [user, loading, router, inviteToken, acceptInvite, nextPath]);
61	
62	  return (
63	    <div className="flex min-h-screen items-center justify-center bg-background px-4">
64	      <Card className="w-full max-w-md shadow-lg border-border/50">
65	        <CardHeader className="text-center space-y-2">
66	          <div className="flex items-center justify-center gap-2 mb-2">
67	            <Zap className="h-7 w-7 text-primary" />
68	            <span className="text-xl font-bold text-foreground tracking-tight">Rankora</span>
69	          </div>
70	          <CardTitle className="text-2xl">
71	            {inviteToken ? "Join Your Team" : "Welcome"}
72	          </CardTitle>
73	          <CardDescription>
74	            {inviteToken
75	              ? "Sign in or create an account to accept the team invitation"
76	              : "Sign in to rank candidates instantly"}
77	          </CardDescription>
78	        </CardHeader>
79	        <CardContent>
80	          <AuthForm onSuccess={() => {
81	            if (inviteToken) {
82	              acceptInvite(inviteToken);
83	            } else {
84	              router.replace(nextPath);
85	            }
86	          }} />
87	        </CardContent>
88	      </Card>
89	    </div>
90	  );
91	};
92	
93	export default Auth;
